INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(34111, 'Revelation 13:11', 'Revelation', 13, 11, 'بیا ما یو بل ځناور ولیده چې د ځمکې نه راووت. هغه د وري په شان دوه ښکرونه لرل او د ښامار په شان یې خبرې کولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation13_verse_11.mp3', '', 1761754199, 1761754199),
(34112, 'Revelation 13:12', 'Revelation', 13, 12, 'هغه د لومړني ځناور په شتون کې د هغه د ټول واک او اختیار څخه کار اخیسته او ټوله ځمکه او د هغې اوسېدونکي یې دې ته مجبورول چې د هغه لومړني حیوان عبادت وکړي چې وژونکی زخم یې جوړ شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation13_verse_12.mp3', '', 1761754199, 1761754199),
(34113, 'Revelation 13:13', 'Revelation', 13, 13, 'هغه لویې معجزې ښودلې، تر دې پورې چې د خلکو په مخکې یې د اسمان نه په ځمکه باندې اور ووراوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation13_verse_13.mp3', '', 1761754199, 1761754199),
(34114, 'Revelation 13:14', 'Revelation', 13, 14, 'هغه په هغو معجزو سره چې اجازه ورکړل شوې وه چې د لومړني ځناور په حضور کې یې وښایي، د ځمکې اوسېدونکي غولول. هغوی ته یې ویل چې د هغه لومړني ځناور مجسمه جوړه کړي چې په توره باندې زخمي شوی ؤ او تر‌اوسه لا ژوندی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation13_verse_14.mp3', '', 1761754199, 1761754199),
(34115, 'Revelation 13:15', 'Revelation', 13, 15, 'هغه ته اجازه ورکړل شوه چې د لومړني ځناور په مجسمه کې ساه واچوي چې خبرې وکړي او وکولای شي هغه خلک ووژني چې د هغې مجسمې عبادت نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation13_verse_15.mp3', '', 1761754199, 1761754199),
(34116, 'Revelation 13:16', 'Revelation', 13, 16, 'هغه ټول خلک د کوچنیو نه نیولې تر لویانو، شتمنو نه تر غریبو، ازادو نه تر غلامانو پورې مجبورول چې په خپل ښي لاس یا تندي باندې یوه نښه ولګوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation13_verse_16.mp3', '', 1761754199, 1761754199),
(34117, 'Revelation 13:17', 'Revelation', 13, 17, 'هېچا نه شو کولای چې څه شی واخلي او یا یې خرڅ کړي، ترڅو پورې چې هغه نښه یا د هغه ځناور د نوم شمېره پرې نه وي لګېدلې چې د هغه د نوم څرګندونه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation13_verse_17.mp3', '', 1761754199, 1761754199),
(34118, 'Revelation 13:18', 'Revelation', 13, 18, 'د دې دپاره پوهه او حکمت په کار دی. نو څوک چې پوه وي باید د هغه ځناور د شمېرې په معنی پوه شي، ځکه چې دا د انسان شمېره ده. هغه شمېره ده ۶۶۶.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation13_verse_18.mp3', '', 1761754199, 1761754199),
(34119, 'Acts 9:1', 'Acts', 9, 1, 'په هماغه وخت کې شاوول لا د څښتن عیسی پیروانو ته د قتل سخت خبردارۍ ورکولې. هغه لوی کاهن ته لاړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_1.mp3', '', 1761754199, 1761754199),
(34120, 'Acts 9:2', 'Acts', 9, 2, 'او د هغه څخه یې وغوښتل چې د دمشق د کنیسو دپاره لیکونه ورکړي چې که چېرې هلته داسې سړي یا ښځې پیدا کړي‎ چې د څښتن عیسی د لارې پیروان وي، نو هغه ونیسي او اورشلیم ته یې راولي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_2.mp3', '', 1761754199, 1761754199),
(34121, 'Acts 9:3', 'Acts', 9, 3, 'کله چې شاوول دمشق ته نژدې کېده، نو ناڅاپه د اسمان څخه یوه رڼا د هغه شاوخوا وځلېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_3.mp3', '', 1761754199, 1761754199),
(34122, 'Acts 9:4', 'Acts', 9, 4, 'هغه په ځمکه باندې راولوېد او یو اواز یې واورېد چې ویل یې: «شاووله، شاووله! ته ولې ما ځوروې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_4.mp3', '', 1761754199, 1761754199),
(34123, 'Acts 9:5', 'Acts', 9, 5, 'شاوول پوښتنه وکړه: «ای څښتنه، ته څوک یې؟» ځواب راغی: «زه عیسی یم، یعنې هغه څوک چې ته یې ځوروې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_5.mp3', '', 1761754199, 1761754199),
(34124, 'Acts 9:6', 'Acts', 9, 6, 'اوس پاڅېږه او ښار ته لاړ شه او هلته به تاته وویل شي چې څه باید وکړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_6.mp3', '', 1761754199, 1761754199),
(34125, 'Acts 9:7', 'Acts', 9, 7, 'کوم کسان چې د شاوول سره په سفر کې ملګري وو، غلي ولاړ وو. هغوی اواز واورېد، خو هېڅوک یې ونه لیده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_7.mp3', '', 1761754199, 1761754199),
(34126, 'Acts 9:8', 'Acts', 9, 8, 'نو شاوول د ځمکې څخه راپورته شو او سره له دې چې سترګې یې غړېدلې، خو څه شی یې نه شو لیدلی. نو ملګرو یې هغه له لاسه ونیوه او دمشق ته یې بوته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_8.mp3', '', 1761754199, 1761754199),
(34127, 'Acts 9:9', 'Acts', 9, 9, 'هغه تر درېو ورځو پورې ړوند ؤ او نه یې څه خوړل او نه یې څښل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_9.mp3', '', 1761754199, 1761754199),
(34128, 'Acts 9:10', 'Acts', 9, 10, 'په دمشق کې یو ایماندار اوسېده چې حنانیا نومېده. هغه رویا ولیدله چې څښتن ورته وویل: «ای حنانیا!» هغه ځواب ورکړ: «ای څښتنه، زه حاضر یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_10.mp3', '', 1761754199, 1761754199),
(34129, 'Acts 9:11', 'Acts', 9, 11, 'څښتن هغه ته وویل: «پاڅېږه او هغې کوڅې ته لاړ شه چې د مستقیمې کوڅې په نوم یادیږي او د یهودا په کور کې د شاوول په نوم د یو تن څخه چې د ترسوس د ښار څخه دی، پوښتنه وکړه. هغه همدا‌اوس دعا کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_11.mp3', '', 1761754199, 1761754199),
(34130, 'Acts 9:12', 'Acts', 9, 12, 'هغه په رویا کې ولیدل چې د حنانیا په نوم یو سړی راځي او د هغه په سر باندې به لاس ږدي، ترڅو هغه بېرته بینا شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_12.mp3', '', 1761754199, 1761754199),
(34131, 'Acts 9:13', 'Acts', 9, 13, 'حنانیا ځواب ورکړ: «ای څښتنه، ډېرو خلکو ماته د دې سړي او د هغو ټولو بدیو په هکله چې هغه په اورشلیم کې ستا د خلکو سره کړي دي، ویلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_13.mp3', '', 1761754199, 1761754199),
(34132, 'Acts 9:14', 'Acts', 9, 14, 'او مشرانو کاهنانو هغه ته اختیار ورکړی چې دمشق ته راشي او هغه ټول خلک چې ستا نوم اخلي، ونیسي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_14.mp3', '', 1761754199, 1761754199),
(34133, 'Acts 9:15', 'Acts', 9, 15, 'خو څښتن هغه ته وویل: «لاړ شه، ځکه چې دا سړی یوه وسیله ده چې ما غوره کړی دی، ترڅو زما نوم غیریهودیانو، د هغوی پاچاهانو او د اسراییلو قوم ته وروپېژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_15.mp3', '', 1761754199, 1761754199),
(34134, 'Acts 9:16', 'Acts', 9, 16, 'زه به په خپله هغه ته وښایم چې هغه باید زما د نوم په خاطر څومره کړاوونه وزغمي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_16.mp3', '', 1761754199, 1761754199),
(34135, 'Acts 9:17', 'Acts', 9, 17, 'نو حنانیا روان شو او هغه کور ته ورننوت چې شاوول په کې اوسېده او خپل لاس یې په شاوول باندې کېښود او ورته ویې ویل: «ای شاووله وروره! کله چې ته دلته راروان وې، نو څښتن یعنې هماغه عیسی چې تاته په لاره کې درښکاره شو، زه رالېږلی یم چې ته بېرته بینا شې او د روح القدس څخه ډک شې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_17.mp3', '', 1761754199, 1761754199),
(34136, 'Acts 9:18', 'Acts', 9, 18, 'سمدلاسه د شاوول د سترګو څخه د پوستکو په شان شیان راوغورځېدل او هغه بېرته بینا شو. بیا هغه راپاڅېده او د تعمید غسل یې واخیست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_18.mp3', '', 1761754199, 1761754199),
(34137, 'Acts 9:19', 'Acts', 9, 19, 'له هغې وروسته هغه ډوډۍ وخوړله او بېرته یې قوت پیدا کړ. شاوول په دمشق کې وعظ کوي شاوول یو څو ورځې په دمشق کې د ایماندارانو سره پاتې شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_19.mp3', '', 1761754199, 1761754199),
(34138, 'Acts 9:20', 'Acts', 9, 20, 'هغه سمدلاسه کنیسو ته لاړ او وعظ یې پیل کړ او ویل یې چې عیسی د خدای زوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_20.mp3', '', 1761754199, 1761754199),
(34139, 'Acts 9:21', 'Acts', 9, 21, 'هرچا چې د هغه خبرې اورېدلې، نو حیران به شول او پوښتنه به یې کوله: «ایا دا هماغه سړی نه دی چې په اورشلیم کې به یې هغه خلک له منځه وړل چې د عیسی نوم به یې یاداوه؟ هغه دلته د دې مقصد دپاره نه دی راغلی چې دا خلک ونیسي او لاس تړلي یې مشرانو کاهنانو ته بوځي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_21.mp3', '', 1761754199, 1761754199),
(34140, 'Acts 9:22', 'Acts', 9, 22, 'خو د شاوول د وعظ کولو قدرت نور هم زیاتېده او په خپلو قانع کوونکو دلیلونو یې ثابتوله چې عیسی هماغه وعده شوی مسیح دی او د دمشق یهودیانو ورته ځواب نه شو ویلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_22.mp3', '', 1761754199, 1761754199),
(34141, 'Acts 9:23', 'Acts', 9, 23, 'ډېره موده وروسته یهودیان سره راټول شول او دسیسه یې جوړه کړه چې شاوول ووژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_23.mp3', '', 1761754199, 1761754199),
(34142, 'Acts 9:24', 'Acts', 9, 24, 'هغوی شپه او ورځ د ښار په دروازو کې څوکیداري کوله، ترڅو هغه ووژني. خو شاوول د هغوی له دسیسې څخه خبر شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_24.mp3', '', 1761754199, 1761754199),
(34143, 'Acts 9:25', 'Acts', 9, 25, 'نو یوه شپه د شاوول پیروانو هغه په ټوکرۍ کې د ښار د دېوال د سوري په لاره راښکته کړ. شاوول په اورشلیم کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_25.mp3', '', 1761754199, 1761754199),
(34144, 'Acts 9:26', 'Acts', 9, 26, 'کله چې شاوول اورشلیم ته ورسېده، نو کوښښ یې وکړ چې د نورو ایماندارانو سره یوځای شي، خو هغوی ټول د هغه څخه وېرېدل، ځکه چې هغوی په دې باور نه درلود چې شاوول په رښتیا سره ایماندار شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_26.mp3', '', 1761754199, 1761754199),
(34145, 'Acts 9:27', 'Acts', 9, 27, 'بیا برناباس د هغه سره مرسته وکړه او هغه یې رسولانو ته بوته او هغوی ته یې وویل چې شاوول څنګه دمشق ته په لاره کې څښتن عیسی ولیده او هغه څنګه د شاوول سره خبرې وکړلې. همدارنګه برناباس هغوی ته وویل چې شاوول څنګه په دمشق کې په زړورتیا سره د عیسی په نوم وعظ وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_27.mp3', '', 1761754199, 1761754199),
(34146, 'Acts 9:28', 'Acts', 9, 28, 'نو شاوول د هغوی سره پاتې شو او په اورشلیم کې د هغوی سره ګرځېده او په زړورتیا سره یې د څښتن عیسی په نوم وعظ کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_28.mp3', '', 1761754199, 1761754199),
(34147, 'Acts 9:29', 'Acts', 9, 29, 'هغه به د یوناني ژبو یهودیانو سره خبرې او بحث کاوه، خو هغوی کوښښ کاوه چې شاوول ووژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_29.mp3', '', 1761754199, 1761754199),
(34148, 'Acts 9:30', 'Acts', 9, 30, 'کله چې ایمانداران د دې څخه خبر شول، نو شاوول یې قیصریې ته بوته او بیا یې هغه د ترسوس ښار ته ولېږه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_30.mp3', '', 1761754199, 1761754199),
(34149, 'Acts 9:31', 'Acts', 9, 31, 'نو په ټوله یهودیه، جلیل او سامره کې کلیسا ارامه وه او قوي شوه. ایماندارانو د څښتن څخه په وېره کې او د روح القدس په مرسته پرمختګ کاوه او شمېر یې زیاتېده. پطروس په لده او یافا کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_31.mp3', '', 1761754199, 1761754199),
(34150, 'Acts 9:32', 'Acts', 9, 32, 'پطروس به هرځای ته سفر کاوه او یوځل هغه د هغو ایماندارانو د لیدلو دپاره چې د لده په ښار کې اوسېدل، لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_32.mp3', '', 1761754199, 1761754199),
(34151, 'Acts 9:33', 'Acts', 9, 33, 'په هغه ځای کې هغه د اینیاس په نوم یو سړی ولیده چې شل ؤ او د اتو کالو راهیسې په کټ کې پروت ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_33.mp3', '', 1761754199, 1761754199),
(34152, 'Acts 9:34', 'Acts', 9, 34, 'پطروس هغه ته وویل: «ای اینیاسه، عیسی مسیح درته شفا درکوي. پاڅېږه او بستره دې راټوله کړه.» او هغه سمدلاسه پاڅېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_34.mp3', '', 1761754199, 1761754199),
(34153, 'Acts 9:35', 'Acts', 9, 35, 'هغو ټولو خلکو چې په لده او شارون کې اوسېدل، اینیاس ولیده او په څښتن عیسی یې ایمان راوړ. پطروس طبیتا بېرته راژوندۍ کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_35.mp3', '', 1761754199, 1761754199),
(34154, 'Acts 9:36', 'Acts', 9, 36, 'د یافا په ښار کې یوه ایمانداره ښځه اوسېدله چې طبیتا نومېدله. (په یوناني ژبه کې د هغې د نوم معنی هوسۍ ده.) هغې تل نېک کارونه کول او د غریبانو سره یې مرسته کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_36.mp3', '', 1761754199, 1761754199),
(34155, 'Acts 9:37', 'Acts', 9, 37, 'په دې وخت کې هغه ناروغه او بیا مړه شوه. خلکو هغې ته غسل ورکړ او پاس په بالاخانه کې یې د هغې مړی کېښود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_37.mp3', '', 1761754199, 1761754199),
(34156, 'Acts 9:38', 'Acts', 9, 38, 'یافا د لدې څخه ډېره لېرې نه وه او ایمانداران خبر شول چې پطروس په لده کې دی، نو هغوی دوه تنه ورولېږل او د هغه څخه یې وغوښتل چې زر تر زره مونږ ته ځان راورسوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_38.mp3', '', 1761754199, 1761754199),
(34157, 'Acts 9:39', 'Acts', 9, 39, 'نو پطروس پاڅېده او د هغوی سره روان شو. کله چې هغه راورسېده، نو پاس بالاخانې ته یې بوته. ټولې کونډې ښځې د هغه څخه راتاوې شوې، هغوی ژړل او هغه کالي او چپنې چې طبیتا د خپل ژوندانه په وخت کې ګنډلي وو، هغه ته وښودل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts9_verse_39.mp3', '', 1761754199, 1761754199),
