(34197, 'Mark 10:36', 'Mark', 10, 36, 'عیسی د هغوی څخه پوښتنه وکړه: «زما څخه څه غواړئ چې درته ویې کړم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_36.mp3', '', 1761754199, 1761754199),
(34198, 'Mark 10:37', 'Mark', 10, 37, 'هغوی ورته وویل: «کله چې ته د خپل جلال څخه ډکې پاچاهۍ په تخت باندې کښېنې، نو مونږ ته اجازه راکړه چې یو ستا ښي لاس ته او بل دې چپ لاس ته کښېنو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_37.mp3', '', 1761754199, 1761754199),
(34199, 'Mark 10:38', 'Mark', 10, 38, 'عیسی هغوی ته وویل: «تاسو نه پوهېږئ چې څه غواړئ. کومه پیاله چې زه یې څښم، تاسو هغه څښلی شئ او یا د تعمید کوم غسل چې ماته راکول کیږي تاسو یې اخیستلی شئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_38.mp3', '', 1761754199, 1761754199),
(34200, 'Mark 10:39', 'Mark', 10, 39, 'هغوی ځواب ورکړ: «هو، مونږ یې کولای شو.» عیسی هغوی ته وویل: «کومه پیاله چې زه څښم، تاسو به یې وڅښئ او د تعمید کوم غسل چې زه یې اخلم، تاسو به یې هم اخلئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_39.mp3', '', 1761754199, 1761754199),
(34201, 'Mark 10:40', 'Mark', 10, 40, 'خو دا زما په اختیار کې نه ده چې څوک به زما ښي یا چپ لاس ته کښېني. دا ځایونه د هغو خلکو دپاره دي چې له مخکې نه ورته تیار شوي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_40.mp3', '', 1761754199, 1761754199),
(34202, 'Mark 10:41', 'Mark', 10, 41, 'کله چې نور لس شاګردان له دې نه خبر شول، نو د یعقوب او یوحنا څخه خفه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_41.mp3', '', 1761754199, 1761754199),
(34203, 'Mark 10:42', 'Mark', 10, 42, 'نو عیسی هغوی راوغوښتل او ورته ویې ویل: «تاسو پوهېږئ چې کوم خلک چې د غیریهودیانو حاکمان ګڼل کیږي، هغوی په خپلو خلکو باندې باداري کوي او مشران یې ورته خپل زور ښایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_42.mp3', '', 1761754199, 1761754199),
(34204, 'Mark 10:43', 'Mark', 10, 43, 'خو په تاسو کې دې داسې نه وي، که په تاسو کې څوک غواړي چې تر ټولو لوی وګڼل شي نو هغه دې ستاسو ټولو خدمتګار شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_43.mp3', '', 1761754199, 1761754199),
(34205, 'Mark 10:44', 'Mark', 10, 44, 'او په تاسو کې چې څوک غواړي مشر شي، نو هغه باید ستاسو ټولو خدمتګار شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_44.mp3', '', 1761754199, 1761754199),
(34206, 'Mark 10:45', 'Mark', 10, 45, 'ځکه چې د انسان زوی د دې دپاره نه دی راغلی چې خدمت یې وشي بلکې د نورو خدمت وکړي او خپل ژوند د ډېرو خلکو دپاره قربان کړي.» عیسی بارتیماوس بینا کوي (متي ۲۰‏:‌۲۹‌‏-‌۳۴ او لوقا ۱۸‏:‌۳۵‌‏-‌۴۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_45.mp3', '', 1761754199, 1761754199),
(34207, 'Mark 10:46', 'Mark', 10, 46, 'بیا هغوی د اریحا ښار ته راغلل او کله چې عیسی د خپلو شاګردانو او ګڼ شمېر خلکو سره د ښار څخه وتلو، نو یو ړوند سوالګر چې بارتیماوس نومېده او د تیماوس زوی ؤ د سرک په غاړه ناست ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_46.mp3', '', 1761754199, 1761754199),
(34208, 'Mark 10:47', 'Mark', 10, 47, 'کله چې هغه خبر شو چې دا ناصري عیسی دی، نو په چیغو وهلو یې پیل وکړ: «ای عیسی، د داود زویه! په ما باندې رحم وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_47.mp3', '', 1761754199, 1761754199),
(34209, 'Mark 10:48', 'Mark', 10, 48, 'ډېرو خلکو هغه ورټلو او ورته ویې ویل چې غلی شه، خو هغه نورې هم چیغې وهلې: «ای د داود زویه، په ما باندې رحم وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_48.mp3', '', 1761754199, 1761754199),
(34210, 'Mark 10:49', 'Mark', 10, 49, 'عیسی ودرېده او ویې ویل: «هغه ته غږ وکړئ چې راشي.» هغوی هغه ړوند سړي ته غږ وکړ او ورته ویې ویل: «خوشحاله اوسه، پاڅېږه، هغه دې غواړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_49.mp3', '', 1761754199, 1761754199);